import {localCreativeTask} from './app.js';
import {localReferenceTask} from './breakdown.js';
const $=id=>document.getElementById(id),token=document.querySelector('meta[name="clippilot-local-token"]')?.content;
const isLocal=token&&['127.0.0.1','localhost'].includes(location.hostname)&&location.protocol==='http:';
if(isLocal){$('local-ai-controls').hidden=false;$('local-ai-status').textContent='本地版已打开。先点击读取模型；如果没有模型，按说明安装本地视觉模型。不使用云模型。'}
async function request(path,data){if(!isLocal)throw Error('请下载并启动本地版，公开站点不访问你的电脑模型');const r=await fetch(path,{method:data?'POST':'GET',headers:{'Content-Type':'application/json','X-ClipPilot-Local':token},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(210000)});const result=await r.json();if(!r.ok)throw Error(result.error||'本地模型请求失败');return result}
$('local-ai-load').onclick=async()=>{try{$('local-ai-load').disabled=true;const data=await request('/api/local/models');$('local-ai-model').replaceChildren();for(const model of data.models){const op=document.createElement('option');op.value=model.name;op.textContent=`${model.name} · ${(model.size/1e9).toFixed(1)}GB`;$('local-ai-model').append(op)}$('local-ai-status').textContent=data.models.length?'已列出本地权重；运行时还会核对视觉能力。模型名称不保证效果。':'未找到本地模型权重；不会自动下载或切换云服务。'}catch(e){$('local-ai-status').textContent=e.message}finally{$('local-ai-load').disabled=false}};
$('local-ai-create').onclick=async()=>{try{const model=$('local-ai-model').value;if(!model)throw Error('请先读取并选择本地视觉模型');const result=await localCreativeTask(context=>request('/api/local/creative',{...context,model}));$('local-ai-output').textContent=result.summary+'\n'+result.method;$('local-ai-status').textContent='已生成可编辑时间线。检查后使用原有导出按钮。'}catch(e){$('local-ai-status').textContent='未采用新方案：'+e.message}};
$('local-ai-analyze').onclick=async()=>{try{const model=$('local-ai-model').value;if(!model)throw Error('请先读取并选择本地视觉模型');const result=await localReferenceTask(context=>request('/api/local/analyze',{...context,model}));$('local-ai-output').textContent=result.analysis;$('local-ai-status').textContent='分析已加入拉片报告；仍需核对推断。'}catch(e){$('local-ai-status').textContent=e.message}};

$('local-ai-shortcut').onclick=()=>{$('local-ai-panel').scrollIntoView({behavior:'smooth',block:'start'})};
